  html, body { margin: 0; width: 1080px; height: 1920px; overflow: hidden; background: #070e19; }
  canvas#gl { position: absolute; inset: 0; width: 1080px; height: 1920px; }
  #ui { position: absolute; inset: 0; pointer-events: none; font-family: 'Plex Latin', 'IBM Plex Sans Arabic', sans-serif; color: #f3eee4; }
  .layer { position: absolute; left: 0; right: 0; text-align: center; will-change: transform, opacity; }
  .eyebrow { font: 500 30px 'Plex Latin', 'IBM Plex Sans Arabic'; letter-spacing: 0.32em; color: #e2c78f; text-transform: uppercase; }
  .rule { height: 2px; width: 120px; margin: 22px auto; background: linear-gradient(90deg, transparent, #c9a96a, transparent); }
  .h1 { font-weight: 600; font-size: 74px; line-height: 1.3; text-shadow: 0 4px 30px rgba(0,0,0,.55); }
  .h2 { font-weight: 500; font-size: 58px; line-height: 1.35; text-shadow: 0 3px 24px rgba(0,0,0,.6); }
  .latin { font-family: 'Cormorant', serif; font-weight: 500; letter-spacing: 0.18em; }
  .gold { color: #e2c78f; }
  html[lang=en] .h1 { font-size: 70px; letter-spacing: -0.01em; }
  html[lang=en] .label .en { text-transform: none; letter-spacing: 0; font: 500 26px 'IBM Plex Sans Arabic'; }
  html[lang=en] .cap { font-size: 38px; }
  .cap { position: absolute; left: 70px; right: 70px; bottom: 330px; text-align: center; font-weight: 500; font-size: 40px; line-height: 1.55; color: #f3eee4; text-shadow: 0 2px 14px rgba(0,0,0,.85), 0 0 2px rgba(0,0,0,.9); }
  .cap span { background: rgba(7,14,25,.58); padding: 6px 18px; border-radius: 10px; -webkit-box-decoration-break: clone; box-decoration-break: clone; }
  .label { position: absolute; transform: translate(-50%, -100%); text-align: center; white-space: nowrap; }
  .label .ar { font-weight: 600; font-size: 42px; text-shadow: 0 2px 16px rgba(0,0,0,.8); }
  .label .en { font: 500 22px 'Plex Latin'; letter-spacing: .28em; color: #e2c78f; text-transform: uppercase; margin-top: 4px; }
  .label .stem { width: 2px; height: 70px; margin: 10px auto 0; background: linear-gradient(#e2c78f, rgba(226,199,143,0)); }
  .chip { display: inline-block; padding: 14px 30px; margin: 0 8px; border: 1.5px solid rgba(226,199,143,.55); border-radius: 60px; font-weight: 500; font-size: 40px; background: rgba(7,14,25,.35); }
  .chip.on { background: rgba(201,169,106,.92); color: #0b1626; border-color: #e2c78f; }
  .check { display: flex; align-items: center; gap: 22px; justify-content: flex-start; font-weight: 500; font-size: 44px; margin: 22px 0; }
  .check i { width: 54px; height: 54px; border-radius: 50%; border: 2px solid #c9a96a; display: inline-flex; align-items: center; justify-content: center; font-style: normal; font-size: 32px; color: #0b1626; }
  .check.on i { background: #c9a96a; }
  .ms { position: absolute; transform: translate(-50%, -50%); text-align: center; font-weight: 600; font-size: 36px; white-space: nowrap; text-shadow: 0 2px 16px rgba(0,0,0,.85); }
  .ms small { display: block; font: 500 20px 'Plex Latin'; letter-spacing: .3em; color: #e2c78f; }
  .foot { position: absolute; left: 0; right: 0; bottom: 250px; text-align: center; font-weight: 300; font-size: 26px; color: rgba(243,238,228,.75); }

