.r2 { position:absolute; left:50px; right:130px; text-align:center; pointer-events:none; color:#1F2937; font-family:'Plex Latin'; }
.r2 .w { display:inline-block; }
.r2-eb { font:600 25px 'Plex Latin'; letter-spacing:.34em; color:#E6D5B8; text-transform:uppercase; }
.r2-rule { width:90px; height:2px; margin:16px auto 18px; background:linear-gradient(90deg,transparent,#E6D5B8,transparent); }
.r2-h { font:700 76px/1.1 'Plex Latin'; letter-spacing:-0.015em; text-shadow:0 6px 36px rgba(0,0,0,.55); }
.r2-h2 { font:700 62px/1.12 'Plex Latin'; letter-spacing:-0.01em; text-shadow:0 5px 30px rgba(0,0,0,.55); }
.r2 .g, .r2 .gg { color:#E6D5B8; }
.r2-word { font:500 116px 'Cormorant'; letter-spacing:.14em; color:#E6D5B8; text-shadow:0 6px 36px rgba(0,0,0,.55); }
.r2-steps { display:flex; justify-content:center; gap:14px; align-items:center; font:600 24px 'Plex Latin'; letter-spacing:.18em; }
.r2-steps .s { color:rgba(31,41,55,.35); } .r2-steps .s.on { color:#1F2937; } .r2-steps .d { width:40px; height:2px; background:rgba(230,213,184,.35); }
.r2-isl { position:absolute; transform:translate(-50%,-100%); text-align:center; white-space:nowrap; }
.r2-isl .n { font:600 38px 'Plex Latin'; text-shadow:0 2px 14px rgba(0,0,0,.9); }
.r2-isl .c { font:500 20px 'Plex Latin'; letter-spacing:.14em; color:#E6D5B8; margin-top:4px; text-shadow:0 2px 10px rgba(0,0,0,.9); }
.r2-isl .ar { font:500 22px 'IBM Plex Sans Arabic'; color:rgba(31,41,55,0.62); margin-top:2px; }
.r2-north { position:absolute; left:64px; top:560px; }
.r2-attr { position:absolute; left:50px; right:130px; top:1448px; text-align:center; font:500 19px 'Plex Latin'; color:rgba(31,41,55,.55); letter-spacing:.04em; }
.r2-room { position:absolute; transform:translate(-50%,-100%); font:600 22px 'Plex Latin'; letter-spacing:.16em; color:#4B5563; background:rgba(230,213,184,.94); padding:7px 14px; border-radius:20px; white-space:nowrap; box-shadow:0 4px 18px rgba(0,0,0,.35); }
.r2-room:after { content:''; position:absolute; left:50%; bottom:-9px; width:2px; height:9px; background:rgba(230,213,184,.94); }
.r2-tl { position:absolute; left:50px; width:900px; top:560px; height:520px; }
.r2-tl .card { position:absolute; inset:0; border-radius:28px; background:rgba(47,53,61,.72); border:1.5px solid rgba(230,213,184,.28); }
.r2-tl .rail { position:absolute; left:120px; right:120px; top:236px; height:4px; border-radius:2px; background:rgba(31,41,55,.16); }
.r2-tl .fill { position:absolute; left:0; top:0; bottom:0; border-radius:2px; background:linear-gradient(90deg,#cdbea4,#E6D5B8); box-shadow:0 0 14px rgba(230,213,184,.55); }
.r2-tl .node { position:absolute; top:220px; width:36px; height:36px; margin-left:-18px; border-radius:50%; border:3px solid rgba(230,213,184,.45); background:#4B5563; }
.r2-tl .node.on { background:#E6D5B8; border-color:#E6D5B8; box-shadow:0 0 0 8px rgba(230,213,184,.16); }
.r2-tl .tick { position:absolute; top:230px; width:2px; height:16px; margin-left:-1px; background:#E6D5B8; }
.r2-tl .col { position:absolute; width:260px; margin-left:-130px; text-align:center; }
.r2-tl .col .ic { height:58px; }
.r2-tl .col .st { font:700 31px 'Plex Latin'; letter-spacing:.12em; margin-top:10px; }
.r2-tl .col .pay { font:700 38px 'Plex Latin'; color:#E6D5B8; }
.r2-tl .col .when { font:500 26px 'Plex Latin'; color:rgba(31,41,55,0.62); margin-top:6px; }
.r2-tl .hdr { position:absolute; left:0; right:0; font:600 21px 'Plex Latin'; letter-spacing:.32em; color:rgba(31,41,55,.45); text-align:center; }
.r2-note { font:500 32px 'Plex Latin'; color:#1F2937; }
.r2-sel { display:flex; flex-direction:column; gap:18px; align-items:stretch; width:620px; margin:0 auto; }
.r2-sel .c { display:flex; align-items:center; gap:22px; padding:18px 28px; border-radius:22px; background:rgba(47,53,61,.74); border:1.5px solid rgba(230,213,184,.25); font:700 44px 'Plex Latin'; color:rgba(31,41,55,.4); }
.r2-sel .c.on { color:#1F2937; border-color:rgba(230,213,184,.8); box-shadow:0 0 24px rgba(230,213,184,.18); }
.r2-sel .c .num { font:600 24px 'Plex Latin'; color:#E6D5B8; letter-spacing:.2em; width:44px; }
.r2-sel .c .ic2 { width:58px; height:58px; border-radius:50%; display:flex; align-items:center; justify-content:center; background:rgba(230,213,184,.1); }
.r2-dd { position:absolute; left:50px; width:900px; }
.r2-dd .row { display:flex; align-items:center; gap:26px; padding:24px 30px; margin-bottom:20px; border-radius:24px; background:rgba(47,53,61,.74); border:1.5px solid rgba(230,213,184,.26); }
.r2-dd .row.on { border-color:rgba(230,213,184,.75); }
.r2-dd .ic { width:76px; height:76px; border-radius:50%; display:flex; align-items:center; justify-content:center; background:rgba(230,213,184,.1); flex:none; }
.r2-dd .tx { flex:1; text-align:left; } .r2-dd .t1 { font:700 44px 'Plex Latin'; } .r2-dd .t2 { font:500 28px 'Plex Latin'; color:rgba(31,41,55,0.62); margin-top:4px; }
.r2-dd .ok { flex:none; width:40px; height:40px; }
.r2-save { display:flex; flex-direction:column; align-items:center; gap:12px; } .r2-save .lbl { font:700 62px 'Plex Latin'; letter-spacing:.04em; text-transform:uppercase; }
.r2-send { display:flex; align-items:center; justify-content:center; gap:14px; font:500 32px 'Plex Latin'; color:rgba(31,41,55,0.62); }
.r2-cap { position:absolute; left:50px; right:130px; top:1290px; text-align:center; }
.r2-cap .box { display:inline-block; padding:12px 24px; border-radius:14px; background:rgba(47,53,61,.7); font:600 42px/1.3 'Plex Latin'; color:#1F2937; }
.r2-cap .cw { color:#E6D5B8; }
